    const marker=new THREE.Mesh(new THREE.RingGeometry(.86,1.12,36),new THREE.MeshBasicMaterial({color:new THREE.Color(color||"#2388c8"),transparent:true,opacity:.82,side:THREE.DoubleSide,depthWrite:false,depthTest:false}));
    marker.rotation.x=-Math.PI/2;marker.position.y=.08;marker.renderOrder=18;root.add(marker);root.userData.physicalMarker=marker;root.userData.remoteRig=rig;root.userData.petKind=kind;root.userData.nameLabel=gca82AttachName(root,name,color,kind==="bird"?4.1:3.75);root.visible=true;root.matrixAutoUpdate=true;
